const html="<!doctype html><html lang=\"ru\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#450d1a\"><title>Куда тебе в финансах? · CUFA</title>\n<style>\n@font-face{font-family:Blacker;src:url(data:font/ttf;base64,) format('truetype');font-weight:100 900;font-style:normal;font-display:swap}\n\n:root{--wine:#450d1a;--sand:#ffe0ad;--paper:#fffcf5;--line:#dbcebd;color:var(--wine);background:var(--paper);font:17px/1.55 Blacker,sans-serif}*{box-sizing:border-box}body{margin:0}header,footer,main{width:min(1160px,90%);margin:auto}header,footer,.row{display:flex;align-items:center;justify-content:space-between;gap:1rem}header{padding:22px 0;border-bottom:1px solid var(--wine)}.brand{display:flex;align-items:center;gap:14px}.brand strong{font-size:28px;letter-spacing:-2px;line-height:1}.brand span{font:14px/1.15 Blacker}small,.tag,.count,button,summary,.eyebrow{font:14px/1.45 Blacker,sans-serif}.eyebrow{letter-spacing:.09em;text-transform:uppercase;font-size:11px;font-weight:bold}main{padding:32px 0;min-height:74vh}.cover{position:relative;background:var(--wine);color:var(--paper);padding:clamp(26px,5vw,72px);overflow:hidden}.cover img{position:absolute;right:5%;top:11%;width:clamp(80px,14vw,175px)}.cover .eyebrow{color:var(--sand)}h1,h2,h3,p{margin:0}h1{font-size:clamp(54px,7.8vw,112px);line-height:.96;letter-spacing:normal;margin:52px 0 22px}h1 .accent{font-weight:normal;color:var(--sand)}.lead{font-size:clamp(19px,2vw,25px);line-height:1.32;max-width:580px}.actions{margin-top:32px;display:flex;flex-wrap:wrap;align-items:center;gap:18px}button{cursor:pointer;color:inherit}.btn{background:var(--wine);color:white;border:0;padding:15px 22px;font-weight:bold}.cover .btn{background:var(--sand);color:var(--wine)}button:focus-visible,summary:focus-visible,a:focus-visible{outline:3px solid #ae7200;outline-offset:3px}.directory{border-block:1px solid var(--line);margin-top:20px;padding:18px 0}summary{cursor:pointer;font-weight:bold}li{margin:6px 0}.directory ul{columns:2}footer{border-top:1px solid var(--line);padding:16px 0 26px;font-size:14px}a{color:inherit}.quiz{max-width:800px;margin:10px auto 45px}.bar{height:5px;background:#eadfce;margin:14px 0 35px}.bar i{display:block;background:var(--wine);height:100%}h2{font-size:clamp(29px,4.7vw,54px);line-height:1.06;letter-spacing:-.035em}.hint{margin:16px 0;color:#745b5b}.opts{display:grid;gap:9px}.opt{display:flex;align-items:center;gap:16px;text-align:left;border:1px solid var(--line);padding:15px 17px;background:white;font:19px/1.35 Blacker,sans-serif}.opt span{font:13px Blacker;border:1px solid var(--line);padding:7px}.opt[aria-pressed=true]{background:var(--sand);border-color:var(--wine)}.opt:hover{border-color:var(--wine)}.nav{margin-top:22px}.link{border:0;background:transparent;text-decoration:underline;padding:10px 0}.btn:disabled{opacity:.4;cursor:default}.result-head{padding:32px;background:var(--wine);color:var(--paper)}.result-head h2{margin:11px 0}.card{padding:24px 0;border-bottom:1px solid var(--line)}h3{font-size:clamp(26px,4vw,38px);line-height:1.12;margin:8px 0}.card p,.card details{max-width:820px;margin-top:12px}.task{padding:16px 20px;background:#f9eacb}.task b{display:block}.group{font-size:23px;margin:30px 0 0}.note{font-size:15px}.count{white-space:nowrap}@media(max-width:640px){header{padding:16px 0}header>small{display:none}.cover img{width:66px;right:18px;top:18px}.cover h1{margin-top:65px}.directory ul{columns:1}main{padding:18px 0}.opt{font-size:17px}.result-head{padding:22px}.actions{gap:12px}.cover .eyebrow{max-width:55%}}\n\n.opt{border:0;border-bottom:1px solid var(--line);min-height:54px}\n.opt span{border:0;font-weight:650;flex:none}\n.brand span{max-width:170px}.link,summary{min-height:44px;align-content:center}.link:disabled{opacity:.45}\n.early{margin-top:14px}.phone{margin-top:16px}.phone img{display:block;width:min(280px,100%);margin:16px 0}.phone a{overflow-wrap:anywhere}\n@media(max-width:640px){header,main,footer{width:calc(100% - 32px)}.opt{padding:14px 10px}.quiz{margin:8px 0 24px}.bar{margin-bottom:22px}.cover h1{font-size:clamp(38px,10vw,64px)}.brand span{font-size:14px}.card,.result-head{overflow-wrap:anywhere}.directory ul{padding-left:22px}}\nh1,h1 .accent{font-weight:325;font-variation-settings:\"wght\" 325}h2,h3,.brand strong{font-weight:500}summary,.btn,.eyebrow,.opt span,.task b{font-weight:400}.phone img{width:min(520px,100%)}\n#app:focus{outline:none}\n.card h3{color:#450d1a}.interpretation{color:#675152;white-space:pre-line;overflow-wrap:anywhere}\n.score-chart{max-width:820px;margin-top:30px;padding:24px 0;border-block:1px solid var(--line)}.score-chart .note{margin:8px 0 18px}.score-list{list-style:none;padding:0;margin:0;display:grid;gap:12px}.score-row{margin:0}.score-label{display:flex;align-items:baseline;justify-content:space-between;gap:12px;font:16px/1.3 Blacker,sans-serif}.score-value{font-variant-numeric:tabular-nums;color:#675152}.score-track{height:8px;background:#eee2d5;margin-top:4px;border-radius:4px;overflow:hidden}.score-fill{height:100%;background:#a16c77;border-radius:inherit}.score-fill.top-score{background:var(--wine)}\n</style>\n<header><div class=\"brand\"><strong>CUFA</strong><span>Central University Finance Association</span></div><small>Карьерный квиз</small></header><main id=\"app\" tabindex=\"-1\"></main><footer><span>Финансовое сообщество ЦУ</span><a href=\"https://t.me/financecu\">@financecu ↗</a></footer>\n<script>\n'use strict';\n/*PUBLIC_CONFIG*/\nconst questions=config.questions, profiles=config.profiles;\nconst app=document.querySelector('#app'), answers=Array(questions.length).fill(null);\nlet step=0;\nconst letters='АБВГ';\nfunction escapeText(value){return value.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('\"','&quot;')}\nfunction show(html){app.innerHTML=html;app.focus({preventScroll:true});window.scrollTo(0,0)}\nfunction home(){show(`<section class=\"cover\"><img src=\"data:image/jpeg;base64,\" alt=\"Central University Finance Association\"><div class=\"eyebrow\">Квиз о карьере</div><h1>Куда тебе<br><span class=\"accent\">в финансах?</span></h1><p class=\"lead\">Выбирай, чем тебе хотелось бы заняться. Уметь всё перечисленное необязательно.</p><div class=\"actions\"><button class=\"btn\" onclick=\"question()\">${answers.some(x=>x!==null)?'Продолжить':'Начать квиз'} &nbsp; →</button><small>${questions.length} вопросов · около 5 минут</small></div><p class=\"note\" style=\"margin-top:16px\">Команда CUFA увидит ответы и итог без имени участника.</p></section><details class=\"phone directory\"><summary>Открыть на телефоне · QR-код</summary><img src=\"${escapeText(config.qr)}\" alt=\"QR-код для перехода к квизу\"><a href=\"${escapeText(config.url)}\">Открыть ссылку на квиз</a></details><details class=\"directory\"><summary>Какие направления есть в квизе? · 11</summary><ul>${Object.values(profiles).map(([name,ru])=>`<li>${name}</li>`).join('')}</ul></details>`)}\nfunction question(){const [prompt,opts]=questions[step];show(`<section class=\"quiz\"><div class=\"row\"><span class=\"eyebrow\">Карьерный квиз</span><span class=\"count\">Вопрос ${step+1} из ${questions.length}</span></div><div class=\"bar\"><i style=\"width:${100*(step+1)/questions.length}%\"></i></div><h2 id=\"prompt\">${escapeText(prompt)}</h2><p class=\"hint\">Выбери один вариант, который тебе ближе.</p><div class=\"opts\" role=\"group\" aria-labelledby=\"prompt\">${opts.map(([id,label],i)=>`<button class=\"opt\" aria-pressed=\"${answers[step]===i}\" onclick=\"choose(${i})\"><span>${letters[i]}</span>${escapeText(label)}</button>`).join('')}</div><div class=\"row nav\"><button class=\"link\" onclick=\"back()\">← Назад</button><button id=\"next\" class=\"btn\" onclick=\"advance()\" ${answers[step]===null?'disabled':''}>${step===questions.length-1?'Мой результат':'Дальше'}</button></div><button class=\"link early\" id=\"finish\" onclick=\"results()\" ${answers.every(x=>x===null)?'disabled':''}>Завершить досрочно</button></section>`)}\nfunction choose(i){answers[step]=i;app.querySelectorAll('.opt').forEach((b,n)=>b.setAttribute('aria-pressed',n===i));document.querySelector('#next').disabled=false;document.querySelector('#finish').disabled=false}\nfunction back(){if(step===0)return home();step--;question()}\nfunction advance(){if(answers[step]===null)return;if(step===questions.length-1)return results();step++;question()}\nfunction ranked(){const scores=Object.fromEntries(Object.keys(profiles).map(id=>[id,{id,total:0,hits:[]}]));questions.forEach(([,opts],n)=>{if(answers[n]===null)return;new Set(opts.map(([id])=>id)).forEach(id=>scores[id].total++);const [id,label]=opts[answers[n]];scores[id].hits.push([n+1,label])});return Object.values(scores).map(s=>({...s,score:config.scheme===\"file28\"?s.hits.length:s.total?s.hits.length/s.total:0})).sort((a,b)=>b.score-a.score)}\nfunction card(s){const [name,,desc]=profiles[s.id];return `<article class=\"card\"><h3>${name}</h3><p class=\"interpretation\">${escapeText(desc)}</p><details><summary>Твои ответы · ${s.hits.length} из ${s.total} возможных</summary><ul>${s.hits.map(([n,t])=>`<li>№ ${n}. ${escapeText(t)}</li>`).join('')}</ul></details></article>`}\nfunction scoreChart(scores){\n const highest=scores[0].score;\n const points=config.scheme==='file28';\n const rows=scores.map(({id,total,score})=>{\n  const name=escapeText(profiles[id][0]);\n  const value=points?String(score):Math.round(score*100)+'%';\n  const width=highest?score/highest*100:0;\n  return `<li class=\"score-row\"><div class=\"score-label\"><span>${name}</span><span class=\"score-value\">${total?value:'—'}</span></div><div aria-hidden=\"true\" class=\"score-track\"><div class=\"score-fill${score===highest?' top-score':''}\" style=\"width:${width}%\"></div></div></li>`;\n }).join('');\n const legend=points?'Каждый выбранный ответ даёт один балл своему направлению.':'Полосы показывают долю выборов направления среди вопросов, в которых оно встречалось.';\n const missing=scores.some(s=>!s.total)?' Прочерк означает, что направление пока не встречалось.':'';\n return `<section class=\"score-chart\" aria-labelledby=\"chart-heading\"><h3 id=\"chart-heading\">Как получился результат</h3><p class=\"note\">${legend}${missing}</p><ol class=\"score-list\" role=\"list\">${rows}</ol></section>`;\n}\nfunction results(){const count=answers.filter(x=>x!==null).length;if(!count)return;const all=ranked(), first=all[0], near=all.filter(s=>s.hits.length && first.score-s.score<=(config.scheme===\"file28\"?0:.101)), next=all.filter(s=>!near.includes(s)&&s.score>0&&s.score>=all[2].score);show(`<section class=\"result-head\"><div class=\"eyebrow\">${count<questions.length?'Предварительный результат':'Результат квиза'} · ${count} из ${questions.length}</div><h2>${near.length===1?'Твой первый ориентир':'Тебе близки несколько направлений'}</h2><p>${near.length===1?'Начни с направления, задачи которого ты выбираешь чаще всего.':'По твоим ответам эти направления близки. Сравни описания и посмотри, какие из твоих ответов привели к каждому направлению.'}</p></section>${near.map(card).join('')}${next.length?'<h3 class=\"group\">Ещё стоит присмотреться</h3>'+next.map(card).join(''):''}${scoreChart(all)}<div class=\"actions\"><button class=\"btn\" onclick=\"resetQuiz()\">Пройти заново</button><button class=\"link\" onclick=\"resume()\">${count<questions.length?'Продолжить квиз':'Вернуться к ответам'}</button></div><p id=\"saved\" role=\"status\" class=\"note\"></p>`);saveResult()}\nlet attempt=crypto.randomUUID(), revision=0;\nasync function saveResult(){\n const status=document.querySelector('#saved');\n if(location.protocol==='file:'){status.textContent='Локальная версия: результат виден только на этом устройстве.';return}\n const payload={edition,attempt,revision:++revision,choices:answers.slice()};\n status.textContent='Сохраняем результат…';\n try{\n  const response=await fetch('/api/results',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),keepalive:true});\n  if(!response.ok)throw Error();\n  status.textContent='Результат сохранён.';\n }catch{\n  status.textContent='Не удалось сохранить результат. ';\n  const retry=document.createElement('button');retry.className='link';retry.textContent='Повторить';retry.onclick=saveResult;status.append(retry);\n }\n}\nfunction resume(){const pending=answers.indexOf(null);if(pending>=0)step=pending;question()}\nfunction resetQuiz(){attempt=crypto.randomUUID();revision=0;answers.fill(null);step=0;question()}\nhome();\n</script></html>\n";
const editor="<!doctype html><html lang=\"ru\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Редактор квиза · CUFA</title>\n<style>\n*{box-sizing:border-box}body{max-width:840px;margin:auto;padding:30px 18px 60px;background:#fffcf5;color:#450d1a;font:17px/1.5 system-ui}h1,h2{font-weight:500;line-height:1.15}a{color:inherit}section{margin-top:28px;border-top:1px solid #dbcbb5;padding-top:10px}label{display:block;margin:12px 0 5px}input,textarea,select,button{font:inherit;color:inherit;max-width:100%}input[type=url],textarea,select{width:100%;padding:9px;background:#fff;border:1px solid #cbb8ad}textarea{resize:vertical}button{background:#450d1a;color:white;border:0;padding:11px 18px;cursor:pointer;margin:8px 4px 8px 0}button:disabled{opacity:.5}img{display:block;width:min(100%,320px);margin:12px 0}.option{padding:5px 0 10px}.option select{width:auto}small{display:block}#status{min-height:24px}.review{background:#f8e9d3;padding:15px}\n</style><a href=\"/admin\">← Результаты</a><h1>Редактор квиза</h1><form id=\"form\" hidden><section><h2>Вопросы и ответы</h2><label for=\"questionNo\">Выбрать вопрос</label><select id=\"questionNo\"></select><label for=\"promptText\">Формулировка вопроса</label><textarea id=\"promptText\" rows=\"2\" required></textarea><div id=\"options\"></div></section>\n<section id=\"interpretations\"><h2>Интерпретации результатов</h2>\n<label for=\"track\">Направление</label><select id=\"track\"></select>\n<label for=\"description\">Что означает результат</label><textarea id=\"description\" rows=\"5\" maxlength=\"4000\" required></textarea>\n\n</section>\n<section><h2>QR-код для участников</h2><label for=\"target\">Ссылка для перехода</label><input id=\"target\" type=\"url\" required><small>При изменении ссылки появится новый QR-код. Можно также загрузить готовый плакат с кодом для этой ссылки.</small><label for=\"upload\">Загрузить изображение (PNG или JPEG, до 1 МБ)</label><input id=\"upload\" type=\"file\" accept=\"image/png,image/jpeg\"><img id=\"poster\" alt=\"Предпросмотр QR-кода\"><a id=\"download\" download=\"QR-CUFA.png\">Скачать изображение</a></section>\n<section><button id=\"publish\" type=\"submit\">Опубликовать изменения</button><p>Изменения увидят участники, которые откроют квиз после публикации.</p></section></form><p id=\"status\" role=\"status\">Загрузка…</p>\n<script src=\"/admin/qr.js\"></script><script>\nconst el=id=>document.getElementById(id);\nlet config,edition,tracks,index=0;\nconst letters='АБВГ';\nfunction message(text){el('status').textContent=text}\nfunction setImage(src){config.qr=src;el('poster').src=src;el('download').href=src;el('download').download=src.startsWith('data:image/jpeg')?'QR-CUFA.jpg':'QR-CUFA.png'}\nfunction displayQuestion(){\n const [prompt,opts]=config.questions[index];el('promptText').value=prompt;el('options').replaceChildren();\n opts.forEach(([id,text],i)=>{\n  const section=document.createElement('div');section.className='option';\n  const label=document.createElement('label'),area=document.createElement('textarea');\n  label.textContent='Ответ '+letters[i];area.value=text;area.rows=2;area.required=true;area.maxLength=700;\n  area.oninput=()=>config.questions[index][1][i][1]=area.value;label.append(area);\n  const link=document.createElement('label'), select=document.createElement('select');link.textContent='Направление ';\n  Object.entries(tracks).forEach(([k,v])=>select.add(new Option(v,k)));select.value=id;\n  select.onchange=()=>config.questions[index][1][i][0]=select.value;link.append(select);\n  section.append(label,link);el('options').append(section);\n })\n}\nfunction displayProfile(){\n const text=config.interpretations[el('track').value];\n el('description').value=text.description;\n}\nel('track').onchange=displayProfile;\nfor(const field of ['description']){\n el(field).oninput=()=>{config.interpretations[el('track').value][field]=el(field).value};\n}\nfunction validUrl(s){try{const u=new URL(s);return u.protocol==='https:'&&!u.username&&!u.password}catch{return false}}\nfunction makeQR(){\n const target=el('target').value.trim();if(!validUrl(target)){el('target').setCustomValidity('Укажи полную HTTPS-ссылку');return false}\n try{const code=qrcode(0,'M');code.addData(new URL(target).href);code.make();\n const n=code.getModuleCount(),unit=10,canvas=document.createElement('canvas');canvas.width=canvas.height=(n+8)*unit;\n const ctx=canvas.getContext('2d');ctx.fillStyle='#ffe0ad';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#450d1a';\n for(let r=0;r<n;r++)for(let c=0;c<n;c++)if(code.isDark(r,c))ctx.fillRect((c+4)*unit,(r+4)*unit,unit,unit);\n config.url=target;setImage(canvas.toDataURL('image/png'));el('upload').value='';return true;\n }catch{el('target').setCustomValidity('Ссылка слишком длинная для QR-кода');return false}\n}\nel('target').oninput=()=>{el('target').setCustomValidity('');makeQR()};\nel('upload').onchange=async()=>{\n const file=el('upload').files[0];if(!file)return;\n if(!['image/png','image/jpeg'].includes(file.type)||file.size>1000000){message('Выбери PNG или JPEG размером до 1 МБ.');return}\n el('publish').disabled=true;\n try{const reader=new FileReader();const data=await new Promise((ok,fail)=>{reader.onload=()=>ok(reader.result);reader.onerror=fail;reader.readAsDataURL(file)});\n const img=new Image();img.src=data;await img.decode();setImage(data);message('Предпросмотр обновлён.')}catch{message('Не удалось прочитать изображение.')}finally{el('publish').disabled=false}\n};\nel('questionNo').onchange=()=>{index=+el('questionNo').value;displayQuestion()};\nel('promptText').maxLength=700;el('promptText').oninput=()=>{config.questions[index][0]=el('promptText').value};\nel('form').onsubmit=async event=>{\n event.preventDefault();el('publish').disabled=true;\n try{\n const incomplete=Object.entries(config.interpretations).find(([,v])=>!v.description.trim());\n if(incomplete){\n  el('track').value=incomplete[0];displayProfile();\n  const field=el('description');\n  field.focus();throw Error('Заполни текст для направления '+tracks[incomplete[0]]+'.');\n }\n const bad=config.questions.findIndex(([p,o])=>!p.trim()||o.some(([,t])=>!t.trim())||(config.scheme!==\"file28\"&&new Set(o.map(([k])=>k)).size!==4));\n if(bad>=0){index=bad;el('questionNo').value=index;displayQuestion();throw Error('Заполни вопрос '+(bad+1)+' и четыре ответа. Проверь выбранные направления.')}\n const r=await fetch('/admin/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({edition,config})});\n if(!r.ok)throw Error(await r.text());edition=(await r.json()).edition;message('Изменения опубликованы. Версия '+edition+'.');\n }catch(e){message(e.message)}finally{el('publish').disabled=false}\n};\nasync function load(){\n const r=await fetch('/admin/config');if(!r.ok)throw Error('Не удалось открыть редактор.');\n const data=await r.json();({config,edition,tracks}=data);\n config.interpretations=data.interpretations;\n Object.entries(tracks).forEach(([key,title])=>el('track').add(new Option(title,key)));\n displayProfile();config.questions.forEach((q,i)=>el('questionNo').add(new Option('Вопрос '+(i+1),i)));\n el('target').value=config.url;setImage(config.qr);displayQuestion();el('form').hidden=false;message('');\n}\nload().catch(e=>message(e.message));\n</script></html>\n";
